/* Vendor-specific OGF 0x3F (opcode & 0xFC00 == 0xFC00): BTC_O, BTC_REJ, BTC_CC, plen 4 — matched by OGF, not listed.
 * Any other opcode: CS, status 0x01, unknown_opcode counter++ (host tests assert zero).                                */

#define BTC_ROW(op_, cls_, act_, gated_, rsp_, plen_, echo_, req_, rsp_id_, so_, sm_, exp_) \
    { (uint16_t)(op_), (uint8_t)(cls_), (uint8_t)(act_), (uint8_t)(gated_), (uint8_t)(rsp_), (uint8_t)(plen_), \
      (uint8_t)(echo_), (uint16_t)(req_), (uint16_t)(rsp_id_), (uint8_t)(so_), (uint8_t)(sm_), (uint8_t)(exp_) },

static const bt_ctrl_cmd_row_t k_rows[] = { BT_CTRL_OPCODE_TABLE(BTC_ROW) };
#define N_ROWS ((uint32_t)(sizeof(k_rows) / sizeof(k_rows[0])))

/* Vendor-specific OGF 0x3F: REJ CC(4), matched by OGF (§8 tail). */
static const bt_ctrl_cmd_row_t k_vendor_row = {
    0xFC00u, BTC_O, BTC_REJ, BTC_REJ, BTC_CC, 4u, BTC_ECHO_NONE, 0u, 0u, 0xFFu, 0u, BTC_EXP_NONE
};

/* ROM payload sizes of the KE command structs (= the ROM param struct size; the struct is the HCI wire layout
 * zero-padded to it, docs/BT_ROM_HCI_MAP.md §1.1). First block: legacy bt_hci.c:882-904 (g_openfw_cmd_tbl min_len,
 * driven on silicon by the legacy phone mode). Second block: stock opcode tables, BT_ROM_HCI_MAP.md §2 "Struct" column
 * (static, cross-checked against the ROM handler). A FWD row without an entry has no verified ROM layout
 * (BT_ROM_INTERFACE §3.2) and fails validation. 0402 (E001, no parameters, stock send_basic) has no entry on purpose:
 * a zero-length layout cannot be expressed here, so a 0402 gate fails validation until that is added. 0x0C13 is the
 * 248 B name plus one: the 249th byte is a NUL guard for ROM handler 0x3ED00's 249-byte scan (review-r1). */
static const struct { uint16_t op; uint8_t min_len; } k_fwd_layout[] = {
    { 0x0C01u,   8u }, { 0x0C13u, 249u }, { 0x0C1Au,   1u }, { 0x0C24u,   3u }, { 0x0C52u, 241u },
    { 0x0C56u,   1u }, { 0x0401u,   5u }, { 0x0405u,  14u }, { 0x0406u,   4u }, { 0x0409u,   7u },
    { 0x040Au,   7u }, { 0x040Bu,  22u }, { 0x040Cu,   6u }, { 0x040Du,  23u }, { 0x040Eu,   6u },
    { 0x042Bu,   9u }, { 0x042Cu,   6u }, { 0x042Du,   6u },
    /* BT_ROM_HCI_MAP.md §2 */
    { 0x0C18u,   2u }, { 0x0C1Cu,   4u }, { 0x0C1Eu,   4u }, { 0x0C3Au,   4u }, { 0x0C45u,   1u },
    { 0x0408u,   6u }, { 0x040Fu,   4u }, { 0x0411u,   2u }, { 0x0413u,   4u }, { 0x0419u,  10u },
    { 0x041Au,   6u }, { 0x041Bu,   2u }, { 0x041Cu,   4u }, { 0x041Du,   2u }, { 0x041Fu,   2u },
    { 0x0434u,   7u }, { 0x0C37u,   4u }, { 0x0C28u,   4u },
};

/* Opcodes bt_ctrl_cmds_reply_syn() implements. */
static const uint16_t k_syn_ops[] = {
    0x0C03u, 0x1005u, 0x0C31u, 0x0C33u, 0x1001u, 0x1009u, 0x1002u, 0x1004u, 0x0C18u, 0x080Fu, 0x0C14u, 0x0C05u, 0x0C12u,
};

static const uint16_t k_exp1_passed[] = { BT_CTRL_EXP1_PASSED_LIST };

static uint8_t s_eff[N_ROWS];
static uint8_t s_supported[BT_CTRL_SUPPORTED_CMDS_LEN];
static uint8_t s_ready;
static int s_errors;

static bool in_list(const uint16_t *list, uint32_t n, uint16_t op)
{
    for (uint32_t i = 0u; i < n; i++) {
        if (list[i] == op) {
            return true;
        }
    }
    return false;
}

uint8_t bt_ctrl_cmds_fwd_min_len(uint16_t opcode)
{
    for (uint32_t i = 0u; i < (uint32_t)(sizeof(k_fwd_layout) / sizeof(k_fwd_layout[0])); i++) {
        if (k_fwd_layout[i].op == opcode) {
            return k_fwd_layout[i].min_len;
        }
    }
    return 0u;
}

int bt_ctrl_cmds_init(void)
{
    if (s_ready) {
        return s_errors;
    }
    int err = 0;
    memset(s_supported, 0, sizeof(s_supported));
    for (uint32_t i = 0u; i < N_ROWS; i++) {
        const bt_ctrl_cmd_row_t *r = &k_rows[i];
        bool passed = in_list(k_exp1_passed, (uint32_t)(sizeof(k_exp1_passed) / sizeof(k_exp1_passed[0])), r->op);
        uint8_t eff = passed ? r->gated : r->act;
        s_eff[i] = eff;
        for (uint32_t j = 0u; j < i; j++) {
            err += (k_rows[j].op == r->op);                                   /* duplicate opcode */
        }
        if (eff == BTC_FWD) {
            uint16_t dest = BT_ROM_MSG_DEST(r->rom_req);
            err += (r->rom_req == 0u || r->rom_rsp == 0u || bt_ctrl_cmds_fwd_min_len(r->op) == 0u ||
                    (dest != BT_ROM_TASK_LM && dest != BT_ROM_TASK_LC));
        }
        if (eff == BTC_SYN) {
            err += !in_list(k_syn_ops, (uint32_t)(sizeof(k_syn_ops) / sizeof(k_syn_ops[0])), r->op);
        }
        err += (eff == BTC_LOCAL) != (r->op == BT_CTRL_OP_HOST_NUM_COMPLETED);
        err += (r->rsp == BTC_NONE) != (eff == BTC_LOCAL);
        err += (r->rsp == BTC_CC && r->plen < 4u);
        err += (r->rsp == BTC_CS && r->plen != 4u);
        err += (r->cls == BTC_M && eff == BTC_REJ);                            /* class M is never REJECT */
        err += (r->echo == BTC_ECHO_BDADDR && (r->rsp != BTC_CC || r->plen < 10u));
        err += (r->echo == BTC_ECHO_HANDLE && (r->rsp != BTC_CC || r->plen < 6u));
        if ((eff == BTC_FWD || eff == BTC_SYN || eff == BTC_LOCAL) && r->so != 0xFFu) {
            if (r->so < BT_CTRL_SUPPORTED_CMDS_LEN) {
                s_supported[r->so] |= r->sm;
            } else {
                err++;
            }
        }
    }
    /* 0C84 Set Min Encryption Key Size must stay unsupported (BT_CTRL_OPCODE_TABLE §3.5). */
    err += (s_supported[45] & 0x80u) != 0u;
    s_errors = err;
    s_ready = 1u;
    return err;
}

const bt_ctrl_cmd_row_t *bt_ctrl_cmds_table(uint32_t *count)
{
    if (count != NULL) {
        *count = N_ROWS;
    }
    return k_rows;
}

const bt_ctrl_cmd_row_t *bt_ctrl_cmds_lookup(uint16_t opcode)
{
    for (uint32_t i = 0u; i < N_ROWS; i++) {
        if (k_rows[i].op == opcode) {
            return &k_rows[i];
        }
    }
    if ((opcode & 0xFC00u) == 0xFC00u) {
        return &k_vendor_row;
    }
    return NULL;
}

uint8_t bt_ctrl_cmds_eff(const bt_ctrl_cmd_row_t *row)
{
    (void)bt_ctrl_cmds_init();
    if (row >= &k_rows[0] && row < &k_rows[N_ROWS]) {
        return s_eff[row - &k_rows[0]];
    }
    return row->act;
}

const uint8_t *bt_ctrl_cmds_supported(void)
{
    (void)bt_ctrl_cmds_init();
    return s_supported;
}

static uint8_t eff_of(uint16_t op)
{
    const bt_ctrl_cmd_row_t *r = bt_ctrl_cmds_lookup(op);
    return r != NULL ? bt_ctrl_cmds_eff(r) : BTC_REJ;
}

void bt_ctrl_cmds_features_p0(uint8_t out[8])
{
    static const uint8_t rom[8] = BT_CTRL_FEAT_P0_ROM;
    static const uint8_t mask[8] = BT_CTRL_FEAT_P0_AND_MASK;
    for (uint32_t i = 0u; i < 8u; i++) {
        out[i] = (uint8_t)(rom[i] & mask[i]);
    }
    if (eff_of(0x0C52u) != BTC_FWD) {
        out[BT_CTRL_FEAT_P0_EIR_BYTE] &= (uint8_t)~BT_CTRL_FEAT_P0_EIR_MASK;
    }
    /* No 0x22/0x2F event packers exist, so inquiry-with-RSSI stays clear whatever the 0C45 gate says. */
    out[BT_CTRL_FEAT_P0_INQRSSI_BYTE] &= (uint8_t)~BT_CTRL_FEAT_P0_INQRSSI_MASK;
}

/* ---- packers ---- */
uint16_t bt_ctrl_pack_cc(uint8_t *out, uint16_t opcode, uint8_t status, const uint8_t *ret, uint8_t ret_len)
{
    if (ret_len > 251u) {
        ret_len = 251u;                    /* 255 - (num_pkts, opcode, status) */
    }
    out[0] = BT_H4_EVT;
    out[1] = BT_HCI_EVT_CC;
    out[2] = (uint8_t)(4u + ret_len);
    out[3] = 1u;                           /* Num_HCI_Command_Packets: constant host window (contract D4) */
    out[4] = (uint8_t)(opcode & 0xFFu);
    out[5] = (uint8_t)(opcode >> 8);
    out[6] = status;
    if (ret_len != 0u) {
        if (ret != NULL) {
            memcpy(&out[7], ret, ret_len);
        } else {
            memset(&out[7], 0, ret_len);
        }
    }
    return (uint16_t)(7u + ret_len);
}

uint16_t bt_ctrl_pack_cs(uint8_t *out, uint16_t opcode, uint8_t status)
{
    out[0] = BT_H4_EVT;
    out[1] = BT_HCI_EVT_CS;
    out[2] = 4u;
    out[3] = status;
    out[4] = 1u;
    out[5] = (uint8_t)(opcode & 0xFFu);
    out[6] = (uint8_t)(opcode >> 8);
    return 7u;
}

uint16_t bt_ctrl_cmds_reply_fail(const bt_ctrl_cmd_row_t *row, uint16_t opcode, const uint8_t *params, uint8_t plen,
                                 uint8_t fail_status, uint8_t *out)
{
    if (row == NULL || row->rsp == BTC_CS) {
        return bt_ctrl_pack_cs(out, opcode, fail_status);
    }
    if (row->rsp == BTC_NONE) {
        return 0u;
    }
    /* Full reply length (the parser checks length before status), zero return parameters, echoed first field. */
    uint8_t ret_len = (uint8_t)(row->plen - 4u);
    uint16_t n = bt_ctrl_pack_cc(out, opcode, fail_status, NULL, ret_len);
    uint8_t echo = row->echo == BTC_ECHO_BDADDR ? 6u : row->echo == BTC_ECHO_HANDLE ? 2u : 0u;
    if (echo > ret_len) {
        echo = ret_len;
    }
    if (echo > plen) {
        echo = plen;
    }
    if (echo != 0u) {
        memcpy(&out[7], params, echo);
    }
    return n;
}

static void put16(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v & 0xFFu);
    p[1] = (uint8_t)(v >> 8);
}

uint16_t bt_ctrl_cmds_reply_syn(const bt_ctrl_cmd_row_t *row, const uint8_t *params, uint8_t plen,
                                const bt_ctrl_cmd_ctx_t *ctx, uint8_t *out)
{
    uint8_t ret[10];
    switch (row->op) {
    case 0x0C03u:                                             /* Reset (§3.8): status of the real reset */
        return bt_ctrl_pack_cc(out, row->op, ctx->reset_status, NULL, 0u);
    case 0x1005u:                                             /* Read Buffer Size (§3.1) */
        put16(&ret[0], BT_CTRL_H2C_ACL_LEN);
        ret[2] = 0u;
        put16(&ret[3], BT_CTRL_H2C_ACL_CREDITS);
        put16(&ret[5], 0u);
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, ret, 7u);
    case 0x1001u:                                             /* Read Local Version (§3.3) */
        ret[0] = BT_CTRL_HCI_VERSION;
        put16(&ret[1], BT_CTRL_HCI_REVISION);
        ret[3] = BT_CTRL_LMP_VERSION;
        put16(&ret[4], BT_CTRL_MANUFACTURER);
        put16(&ret[6], BT_CTRL_LMP_SUBVER);
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, ret, 8u);
    case 0x1009u:                                             /* Read BD_ADDR (§3.4) */
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, ctx->bd_addr, 6u);
    case 0x1002u:                                             /* Read Local Supported Commands (§3.5) */
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, bt_ctrl_cmds_supported(), BT_CTRL_SUPPORTED_CMDS_LEN);
    case 0x1004u: {                                           /* Read Local Extended Features (§3.6) */
        uint8_t page = plen >= 1u ? params[0] : 0u;
        memset(ret, 0, 10u);
        ret[0] = page;
        ret[1] = BT_CTRL_EXT_FEAT_MAX_PAGE;
        if (plen >= 1u && page == 0u) {
            bt_ctrl_cmds_features_p0(&ret[2]);
        } else if (plen >= 1u && page == 1u) {
            ret[2] = ctx->ssp_host ? BT_CTRL_FEAT_P1_SSP_HOST : 0u;
        } else {
            return bt_ctrl_pack_cc(out, row->op, BT_HCI_ERR_INVALID_PARAMS, ret, 10u);
        }
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, ret, 10u);
    }
    case 0x0C14u:                                             /* Read Local Name (§3.7) */
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, ctx->local_name, BT_CTRL_NAME_LEN);
    case 0x0C12u:                                             /* Delete Stored Link Key: num_deleted = 0 (exact) */
        put16(&ret[0], 0u);
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, ret, 2u);
    case 0x0C05u:                                             /* Set Event Filter: exact only for (01,00) / (00) */
        if ((plen == 2u && params[0] == 0x01u && params[1] == 0x00u) || (plen == 1u && params[0] == 0x00u)) {
            return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, NULL, 0u);
        }
        return bt_ctrl_cmds_reply_fail(row, row->op, params, plen, BT_HCI_ERR_UNKNOWN_CMD, out);
    case 0x0C31u:                                             /* side effects applied by bt_ctrl (§3.2) */
    case 0x0C33u:
    case 0x0C18u:                                             /* exact while the value is the default 0x2000 */
    case 0x080Fu:                                             /* exact: no LMP link modes advertised */
        return bt_ctrl_pack_cc(out, row->op, BT_HCI_OK, NULL, 0u);
    default:
        return bt_ctrl_cmds_reply_fail(row, row->op, params, plen, BT_HCI_ERR_UNKNOWN_CMD, out);
    }
}
